type householdWhere[Q psql.Filterable] struct {
	cols                     householdColumns
	ID                       psql.WhereMod[Q, uuid.UUID]
	Name                     psql.WhereMod[Q, string]
	Revision                 psql.WhereMod[Q, int64]
	DefaultAllocationVersion psql.WhereMod[Q, int64]
	CreatedAt                psql.WhereMod[Q, time.Time]
	UpdatedAt                psql.WhereMod[Q, time.Time]
	R                        householdWhereR[Q]
}

func (householdWhere[Q]) AliasedAs(alias string) householdWhere[Q] {
	return buildHouseholdWhere[Q](buildHouseholdColumns(alias))
}

func buildHouseholdWhere[Q psql.Filterable](cols householdColumns) householdWhere[Q] {
	return householdWhere[Q]{
		cols:                     cols,
		ID:                       psql.Where[Q, uuid.UUID](cols.ID.Expression),
		Name:                     psql.Where[Q, string](cols.Name.Expression),
		Revision:                 psql.Where[Q, int64](cols.Revision.Expression),
		DefaultAllocationVersion: psql.Where[Q, int64](cols.DefaultAllocationVersion.Expression),
		CreatedAt:                psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:                psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		R:                        householdWhereR[Q]{cols: cols},
	}
}

// householdWhereR holds the relationship-based filters of
// householdWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
